/* ================= 通用 SVG 辅助 ================= */
function hexVerts(cx,cy,r){
  const v=[];
  for(let i=0;i<6;i++){const a=-Math.PI/2+i*Math.PI/3;v.push([cx+r*Math.cos(a),cy+r*Math.sin(a)]);}
  return v;
}
function ptsStr(v){return v.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ');}
function ringSvg(cx,cy,r,stroke){
  stroke=stroke||'#334155';
  const v=hexVerts(cx,cy,r);
  return '<polygon points="'+ptsStr(v)+'" fill="#fff" stroke="'+stroke+'" stroke-width="2" stroke-linejoin="round"/>'+
         '<circle cx="'+cx+'" cy="'+cy+'" r="'+(r*0.56).toFixed(1)+'" fill="none" stroke="'+stroke+'" stroke-width="1.8"/>';
}
function subSvg(cx,cy,r,idx,text,color){
  const a=-Math.PI/2+idx*Math.PI/3;
  const x=cx+(r+16)*Math.cos(a), y=cy+(r+16)*Math.sin(a);
  return '<text x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" font-size="15" font-weight="700" fill="'+(color||'#0f172a')+
         '" text-anchor="middle" dominant-baseline="central">'+text+'</text>';
}
function bond(x1,y1,x2,y2,color,w){
  return '<line x1="'+x1.toFixed(1)+'" y1="'+y1.toFixed(1)+'" x2="'+x2.toFixed(1)+'" y2="'+y2.toFixed(1)+
         '" stroke="'+(color||'#334155')+'" stroke-width="'+(w||2)+'" stroke-linecap="round"/>';
}
function txt(x,y,s,size,color,anchor,weight){
  return '<text x="'+x+'" y="'+y+'" font-size="'+(size||13)+'" fill="'+(color||'#0f172a')+'" font-weight="'+(weight||500)+
         '" text-anchor="'+(anchor||'middle')+'" dominant-baseline="central">'+s+'</text>';
}

