var P5OPTS=[
  [ {t:'O₂ / Cu，加热',ok:true}, {t:'H₂ / Ni',ok:false}, {t:'浓硫酸，170 ℃',ok:false} ],
  [ {t:'CH₃NO₂ / 碱（KF、NaOH）',ok:true}, {t:'CH₃Cl / 碱',ok:false}, {t:'Br₂ / CCl₄',ok:false} ],
  [ {t:'H₂ / Ni（或 Fe / HCl）',ok:true}, {t:'NaHCO₃ 溶液',ok:false}, {t:'稀盐酸',ok:false} ]
];

function p5Render(){
  document.getElementById('p5mol').innerHTML=P5MOL[P5.stage];
  var side=document.getElementById('p5side');
  var hint=document.getElementById('p5hint');
  var h='';
  if(P5.stage<3){
    var titles=[
      '第 1 步：把 –CH₂OH 变成 –CHO（氧化）',
      '第 2 步：让甲醛基邻位“长”出 –CH₂NO₂（Henry 反应）',
      '第 3 步：把 –NO₂ 还原成 –NH₂'
    ];
    h+='<div class="qtag">第（7）问 · 第 '+(P5.stage+1)+' 步</div>';
    h+='<div class="qtext">'+titles[P5.stage]+'</div>';
    P5OPTS[P5.stage].forEach(function(o,k){
      var cls='opt';
      if(P5.wrong===''+P5.stage+k && !o.ok) cls+=' wrong';
      h+='<button class="'+cls+'" data-s="'+P5.stage+'" data-k="'+k+'">'+o.t+'</button>';
    });
    if(P5.wrong){
      h+='<div class="hint bad">再想想：这一步需要的是哪种反应？</div>';
    }
  } else {
    h+='<div class="qtag">第（7）问 · 答案</div>';
    h+='<div class="answer"><b>合成路线（三步）：</b><br>'+
       '① Ar–CH₂OH &nbsp;<span style="color:#2563eb">O₂/Cu，Δ</span>&nbsp;→ Ar–CHO<br>'+
       '② Ar–CHO + CH₃NO₂ &nbsp;<span style="color:#2563eb">碱</span>&nbsp;→ Ar–CH(OH)CH₂NO₂<br>'+
       '③ Ar–CH(OH)CH₂NO₂ &nbsp;<span style="color:#2563eb">H₂/Ni</span>&nbsp;→ Ar–CH(OH)CH₂NH₂</div>';
    h+='<div class="btnrow" style="margin-top:12px"><button class="act ghost" id="p5reset">重新做一次</button></div>';
  }
  side.innerHTML=h;
  hint.textContent=P5.stage===3?'Ar = 2,4-二氯苯基。':'注意：不要破坏苯环上的 –Cl，也不要把羟基一起氧化掉。';

  side.querySelectorAll('button.opt').forEach(function(b){
    b.addEventListener('click',function(){
      var s=parseInt(b.dataset.s,10), k=parseInt(b.dataset.k,10);
      if(P5OPTS[s][k].ok){
        P5.wrong=''; P5.stage=s+1; p5Render();
      } else {
        P5.wrong=''+s+k; p5Render();
      }
    });
  });
  var r=document.getElementById('p5reset');
  if(r) r.addEventListener('click',function(){ P5.stage=0; P5.wrong=''; p5Render(); });
}
p5Render();
</script>
